        var sum = a.Value + b.Value;                 // 无 checked：ulong 环绕检测
        return sum < a.Value ? Top : Of(sum);        // sum < 任一操作数 ⇒ 环绕 ⇒ 保守 ⊤（非负值，不溢出到负）
    }

    // §3.1.5a 乘法律：x×⊤=⊤(x>0)；0×⊤=⊤（保守标记未知，MA-002）；⊤×⊤=⊤；溢出（ulong 静默环绕）⇒ ⊤ 保守。
